// AI generated by: Claude Code (claude-opus-5-5)
// Prompt: "Could you create a small tool that would simulate the whole working
// on the parser and semantics, it should have a input field where there would
// be a picker of token from one to send simulated token from lexer. then there
// should be a rendered AST section and block section. Also add some example
// scenarious covering the different parser-semantic scenarious. Do it with
// simple HTML, CSS and typescript if you need that for functionality" +
// "also create a separate branch for it"
// Changes: new file, the page logic: token picker, playback of the token
// stream, AST, blocks/scopes, parser state and trace rendering on top of
// engine.js (Sim) and scenarios.js (SCENARIOS).

// @ts-check
"use strict";

(() => {
  const SimApi = /** @type {any} */ (globalThis).Sim;
  const scenarios = /** @type {any[]} */ (/** @type {any} */ (globalThis).SCENARIOS);
  const STORE_KEY = "ifj26-parser-sim";

  /** @param {string} id */
  const $ = (id) => /** @type {HTMLElement} */ (document.getElementById(id));

  /** @type {any} the last simulation, reused by hover highlighting */
  let last = null;

  const state = {
    /** @type {{type: string, value?: any}[]} */
    tokens: [],
    sent: 0,
    scenario: "",
    view: "parse",
    trace: "sema",
    /** ids of AST nodes that existed before the last change, to flash new ones */
    known: -1,
    /** @type {number|null} */
    focusNode: null,
    /** @type {number|null} */
    hoverToken: null,
    hadSema: false,
  };

  // === HELPERS ===

  /** @param {string} s */
  function esc(s) {
    return String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c] || c);
  }

  /** @param {string} tag @param {Record<string, any>} [attrs] @param {(Node|string)[]} [kids] */
  function el(tag, attrs = {}, kids = []) {
    const node = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (v === undefined || v === null || v === false) continue;
      if (k === "class") node.className = v;
      else if (k === "html") node.innerHTML = v;
      else if (k.startsWith("on")) node.addEventListener(k.slice(2), v);
      else node.setAttribute(k, v === true ? "" : String(v));
    }
    for (const kid of kids) node.append(kid);
    return node;
  }

  function save() {
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify({ tokens: state.tokens, sent: state.sent, scenario: state.scenario }));
    } catch (_) { /* storage may be unavailable */ }
  }

  function load() {
    try {
      const raw = localStorage.getItem(STORE_KEY);
      if (!raw) return false;
      const data = JSON.parse(raw);
      if (!Array.isArray(data.tokens)) return false;
      state.tokens = data.tokens;
      state.sent = Math.min(Number(data.sent) || 0, data.tokens.length);
      state.scenario = data.scenario || "";
      return true;
    } catch (_) {
      return false;
    }
  }

  /** Short label of a raw token in the stream @param {{type: string, value?: any}} t */
  function tokenLabel(t) {
    switch (t.type) {
      case "INDENT": return `L${t.value}`;
      case "EOL_TOKEN": return "EOL";
      case "EOF_TOKEN": return "EOF";
      case "BREAK": return "BREAK";
      case "WHITESPACE": return "␠";
      case "IDENT": return String(t.value);
      case "STRING": return JSON.stringify(t.value);
      case "TRIPLE_STRING": return `"""${t.value}"""`;
      case "NUMBER_INT":
      case "NUMBER_DOUBLE": return String(t.value);
      case "TYPE_UNIT": return "()";
      case "S_STRING_START": return 's"';
      case "S_STRING_END": return '"';
      case "TRIPLE_S_STRING_START": return 's"""';
      case "TRIPLE_S_STRING_END": return '"""';
      case "DOLLAR_EXPRESSION_START": return "${";
      case "DOLLAR_EXPRESSION_END": return "}";
      default: return SimApi.info(t.type).name;
    }
  }

  /** @param {string} type */
  function isLayout(type) {
    return ["INDENT", "EOL_TOKEN", "EOF_TOKEN", "BREAK", "WHITESPACE"].includes(type);
  }

  /** @param {string} kind */
  function kindClass(kind) {
    if (["PROGRAM", "DEF", "PARAM_LIST", "PARAM", "BLOCK", "TYPE_ANNOTATION", "NONE"].includes(kind)) return "k-struct";
    if (["VAL", "VAR", "ASSIGN", "RETURN", "IF", "WHILE", "FOR"].includes(kind)) return "k-stmt";
    if (kind === "INT_TO_DOUBLE") return "k-sema";
    if (["IDENT", "INT_LIT", "DOUBLE_LIT", "STRING_LIT", "BOOL_LIT", "UNIT_LIT"].includes(kind)) return "k-leaf";
    return "k-expr";
  }

  const ROLES = {
    DEF: ["ident", "rettype", "body", "params"],
    PARAM: ["ident", "type"],
    VAL: ["ident", "type", "init"],
    VAR: ["ident", "type", "init"],
    ASSIGN: ["target", "value"],
    RETURN: ["value"],
    IF: ["cond", "then", "else"],
    WHILE: ["cond", "body"],
    FOR: ["var", "source", "body"],
    RANGE_TO: ["from", "to", "step"],
    RANGE_UNTIL: ["from", "until", "step"],
    MEMBER: ["receiver"],
    NOT: ["operand"],
    NEG: ["operand"],
    INT_TO_DOUBLE: ["operand"],
  };
  const BINARY = new Set(["ADD", "SUB", "MUL", "DIV", "EQ", "NEQ", "LT", "GT", "LE", "GE", "AND", "OR"]);

  /** @param {any} parent @param {number} i */
  function role(parent, i) {
    if (!parent) return "";
    if (BINARY.has(parent.kind)) return i === 0 ? "left" : "right";
    if (parent.kind === "CALL") return i === 0 ? "callee" : `arg ${i}`;
    if (parent.kind === "FOR" && i >= 3) return `guard ${i - 2}`;
    const r = /** @type {any} */ (ROLES)[parent.kind];
    return r && r[i] ? r[i] : String(i);
  }

  // === PICKER ===

  function fillPickers() {
    const typeSelect = /** @type {HTMLSelectElement} */ ($("token-type"));
    /** @type {Map<string, HTMLOptGroupElement>} */
    const groups = new Map();
    for (const t of SimApi.TOKEN_TYPES) {
      if (!groups.has(t.group)) {
        const g = document.createElement("optgroup");
        g.label = t.group;
        groups.set(t.group, g);
        typeSelect.append(g);
      }
      const label = t.label === t.type ? t.type : `${t.label}  ·  ${t.type}`;
      /** @type {HTMLOptGroupElement} */ (groups.get(t.group)).append(new Option(label, t.type));
    }
    typeSelect.value = "IDENT";

    const sc = /** @type {HTMLSelectElement} */ ($("scenario"));
    sc.append(new Option("✎ Empty — build your own", ""));
    /** @type {Map<string, HTMLOptGroupElement>} */
    const sg = new Map();
    for (const s of scenarios) {
      if (!sg.has(s.group)) {
        const g = document.createElement("optgroup");
        g.label = s.group;
        sg.set(s.group, g);
        sc.append(g);
      }
      /** @type {HTMLOptGroupElement} */ (sg.get(s.group)).append(new Option(`${s.title}  (exit ${s.expect})`, s.id));
    }
  }

  function syncValueField() {
    const type = /** @type {HTMLSelectElement} */ ($("token-type")).value;
    const spec = SimApi.TOKEN_BY_TYPE.get(type);
    const input = /** @type {HTMLInputElement} */ ($("token-value"));
    if (!spec || !spec.valueKind) {
      input.disabled = true;
      input.value = "";
      input.placeholder = "no value";
      return;
    }
    input.disabled = false;
    input.placeholder = { indent: "spaces", int: "integer", double: "number", text: "text" }[/** @type {string} */ (spec.valueKind)] || "value";
    if (input.dataset.for !== type) {
      input.value = String(spec.defaultValue);
      input.dataset.for = type;
    }
  }

  /** @param {string} type @param {string} rawValue @returns {{type: string, value?: any}|null} */
  function makeToken(type, rawValue) {
    const spec = SimApi.TOKEN_BY_TYPE.get(type);
    if (!spec) return null;
    if (!spec.valueKind) return { type };
    if (spec.valueKind === "indent" || spec.valueKind === "int") {
      const n = Number.parseInt(rawValue, 10);
      if (!Number.isFinite(n) || n < 0) return null;
      return { type, value: n };
    }
    if (spec.valueKind === "double") {
      const n = Number.parseFloat(rawValue);
      if (!Number.isFinite(n)) return null;
      return { type, value: n };
    }
    if (type === "IDENT" && !/^[A-Za-z_][A-Za-z0-9_]*$/.test(rawValue)) return null;
    return { type, value: rawValue };
  }

  /** @param {{type: string, value?: any}[]} toks */
  function send(...toks) {
    state.tokens = state.tokens.slice(0, state.sent).concat(toks);
    state.sent = state.tokens.length;
    if (state.scenario) state.scenario = "";
    /** @type {HTMLSelectElement} */ ($("scenario")).value = "";
    render();
  }

  // === RENDERING ===

  function render() {
    const prefix = state.tokens.slice(0, state.sent);
    const r = SimApi.simulate(prefix);
    if (r.semaTree && !state.hadSema && state.view === "parse") state.view = "sema";
    state.hadSema = !!r.semaTree;
    renderAbout();
    renderStatus(r);
    renderStream(r);
    renderSource(r);
    renderPalette(prefix, r);
    renderAst(r);
    renderBlocks(r);
    renderParserState(r);
    renderTrace(r);
    state.known = r.idCount;
    last = r;
    save();
  }

  function renderAbout() {
    const box = $("scenario-about");
    const s = scenarios.find((x) => x.id === state.scenario);
    if (!s) {
      box.hidden = true;
      return;
    }
    box.hidden = false;
    box.innerHTML = `<strong>${esc(s.title)}</strong><span class="expect">expected exit ${s.expect} — ${esc(SimApi.EXIT_NAMES[s.expect])}</span><br>${esc(s.about)}`;
  }

  /** @param {any} r */
  function renderStatus(r) {
    const box = $("status");
    const scenario = scenarios.find((x) => x.id === state.scenario);
    const done = state.sent === state.tokens.length;
    let match = "";
    if (scenario && done && r.exitCode !== null)
      match = r.exitCode === scenario.expect
        ? `<span class="match">✓ matches the expected exit ${scenario.expect}</span>`
        : `<span class="match">✗ expected exit ${scenario.expect}</span>`;

    if (r.status === "waiting") {
      box.className = r.viable ? "status waiting" : "status dead";
      const where = r.callStack && r.callStack.length ? r.callStack[r.callStack.length - 1] : "PROGRAM";
      box.innerHTML = r.viable
        ? `<strong>Waiting for the next token</strong> in <code>${esc(where)}</code>` +
          (state.sent === 0 ? `<span class="msg">Start with a raw indent L0, then import ifj26 . * EOL — or pick an example scenario.</span>` : "")
        : `<strong>Dead end</strong> the precedence parser is still waiting, but no token can complete this expression; it reports the syntax error at the next reduction.`;
    } else if (r.status === "error") {
      box.className = "status error";
      box.innerHTML = `<strong>Exit ${r.exitCode}</strong> ${esc(SimApi.EXIT_NAMES[r.exitCode] || "")}${match}<span class="msg">${esc(r.error.message)}</span>`;
    } else if (r.status === "ok") {
      box.className = "status ok";
      box.innerHTML = `<strong>Exit 0</strong> parsed and semantically valid${match}`;
    } else {
      box.className = "status parsed";
      box.innerHTML = `<strong>Parsed</strong>`;
    }
  }

  /** @param {any} r */
  function renderStream(r) {
    const box = $("stream");
    box.textContent = "";
    const errIndex = r.error && r.error.tokenIndex >= 0 ? r.error.tokenIndex : -1;
    state.tokens.forEach((t, i) => {
      const cls = ["tok"];
      if (isLayout(t.type)) cls.push("layout");
      if (i >= state.sent) cls.push("pending");
      if (i === state.sent - 1) cls.push("last");
      if (i === errIndex) cls.push("error");
      box.append(el("button", {
        type: "button", class: cls.join(" "), title: `#${i + 1} ${t.type}${t.value !== undefined ? " = " + JSON.stringify(t.value) : ""}`,
        onclick: () => { state.sent = i + 1; render(); },
      }, [tokenLabel(t)]));
      if (t.type === "EOL_TOKEN") box.append(el("span", { class: "tok br" }));
    });
    if (!state.tokens.length) box.append(el("span", { class: "muted" }, ["No tokens yet."]));
    $("position").textContent = `${state.sent} / ${state.tokens.length}`;
    /** @type {HTMLButtonElement} */ ($("btn-back")).disabled = state.sent === 0;
    /** @type {HTMLButtonElement} */ ($("btn-start")).disabled = state.sent === 0;
    /** @type {HTMLButtonElement} */ ($("btn-step")).disabled = state.sent >= state.tokens.length;
    /** @type {HTMLButtonElement} */ ($("btn-end")).disabled = state.sent >= state.tokens.length;
    const last = box.querySelector(".tok.last");
    if (last) last.scrollIntoView({ block: "nearest" });
  }

  /** @param {any} r */
  function renderSource(r) {
    const { text, spans } = r;
    const errIndex = r.error && r.error.tokenIndex >= 0 ? r.error.tokenIndex : -1;
    let html = "";
    let pos = 0;
    spans.forEach((/** @type {{start: number, end: number}} */ s, /** @type {number} */ i) => {
      html += esc(text.slice(pos, s.start));
      const cls = [];
      if (i === state.sent - 1) cls.push("hl");
      if (i === errIndex) cls.push("err");
      if (i === state.hoverToken) cls.push("hover");
      const piece = esc(text.slice(s.start, s.end));
      html += cls.length ? `<span class="${cls.join(" ")}">${piece || " "}</span>` : piece;
      pos = s.end;
    });
    html += esc(text.slice(pos));
    if (r.status === "waiting") html += '<span class="cursor"></span>';
    $("source").innerHTML = html;
  }

  /** @param {any[]} prefix @param {any} r */
  function renderPalette(prefix, r) {
    const box = $("palette");
    box.textContent = "";
    const hint = $("accept-hint");
    if (r.status === "error" || r.status === "ok" || r.status === "parsed") {
      hint.textContent = "";
      box.append(el("div", { class: "empty" }, [r.status === "error"
        ? "Compilation stopped. Step back (◀) or click a token in the stream to rewind."
        : "The program is complete."]));
      return;
    }
    const ok = SimApi.acceptableNext(prefix);
    hint.textContent = `${ok.size} token type${ok.size === 1 ? "" : "s"}, click to send`;
    if (!ok.size) {
      box.append(el("div", { class: "empty" }, ["No token can continue this program."]));
      return;
    }
    /** @type {Map<string, HTMLElement>} */
    const groups = new Map();
    for (const spec of SimApi.TOKEN_TYPES) {
      const values = ok.get(spec.type);
      if (!values) continue;
      if (!groups.has(spec.group)) {
        const g = el("div", { class: "palette-group" }, [el("span", {}, [spec.group])]);
        groups.set(spec.group, g);
        box.append(g);
      }
      const g = /** @type {HTMLElement} */ (groups.get(spec.group));
      if (spec.type === "INDENT") {
        for (const v of values)
          g.append(chip(`L${v}`, `raw INDENT ${v}`, () => send({ type: "INDENT", value: v })));
      } else if (spec.type === "IDENT" && !values.includes("x")) {
        for (const v of values)
          g.append(chip(v, `identifier "${v}", a contextual keyword here`, () => send({ type: "IDENT", value: v })));
      } else if (spec.valueKind) {
        g.append(chip(spec.label, `${spec.type}: type the value, then Send`, () => {
          /** @type {HTMLSelectElement} */ ($("token-type")).value = spec.type;
          syncValueField();
          const input = /** @type {HTMLInputElement} */ ($("token-value"));
          input.focus();
          input.select();
        }));
      } else {
        g.append(chip(spec.label, spec.type, () => send({ type: spec.type })));
      }
    }
  }

  /** @param {string} label @param {string} title @param {() => void} onclick */
  function chip(label, title, onclick) {
    return el("button", { type: "button", class: "chip ok", title, onclick }, [label]);
  }

  // --- AST ---

  /** @param {any} r */
  function renderAst(r) {
    for (const b of document.querySelectorAll("[data-view]"))
      b.setAttribute("aria-selected", String(/** @type {HTMLElement} */ (b).dataset.view === state.view));
    const box = $("ast");
    box.textContent = "";
    const badId = r.error && r.error.node ? r.error.node.id : null;

    if (state.view === "sexpr") {
      const tree = r.semaTree || r.parseTree;
      if (!tree) return box.append(placeholder("Nothing parsed yet."));
      const parse = SimApi.toTestString(r.parseTree);
      const parts = [el("h3", {}, ["Parser output"]), el("pre", {}, [parse])];
      if (r.semaTree) parts.push(el("h3", {}, ["After semantic analysis"]), el("pre", {}, [SimApi.toTestString(r.semaTree)]));
      parts.push(el("div", { class: "card-foot" }, [el("button", {
        type: "button", onclick: (/** @type {Event} */ e) => copy(r.semaTree ? SimApi.toTestString(r.semaTree) : parse, /** @type {HTMLElement} */ (e.target)),
      }, ["Copy"])]));
      parts.forEach((p) => box.append(p));
      return;
    }

    const tree = state.view === "sema" ? r.semaTree : r.parseTree;
    if (!tree) {
      box.append(placeholder(state.view === "sema"
        ? "Semantic analysis runs once the whole program is parsed: send EOF."
        : "Send the first tokens (L0 import …) to create the PROGRAM node."));
      return;
    }
    const tokenAt = tokenIndexByPosition(r.tokens);
    const ul = el("ul");
    ul.append(renderNode(tree, null, 0, badId, tokenAt));
    box.append(ul);

    // subtrees still on the precedence stack are not attached yet
    if (state.view === "parse" && r.status !== "parsed" && r.status !== "ok") {
      const pending = r.prec.filter((/** @type {any} */ e) => e.node);
      if (pending.length) {
        box.append(el("h3", {}, ["On the precedence stack, not attached yet"]));
        const pl = el("ul");
        for (const e of pending) pl.append(renderNode(e.node, null, 0, badId, tokenAt, true));
        box.append(pl);
      }
    }
    if (state.focusNode !== null) {
      const row = box.querySelector(`[data-id="${state.focusNode}"]`);
      if (row) {
        row.classList.add("new");
        row.scrollIntoView({ block: "center" });
      }
      state.focusNode = null;
    }
  }

  /** @param {string} text */
  function placeholder(text) {
    return el("p", { class: "placeholder" }, [text]);
  }

  /** @param {any[]} tokens */
  function tokenIndexByPosition(tokens) {
    /** @type {Map<string, number>} */
    const map = new Map();
    tokens.forEach((t, i) => {
      if (isLayout(t.type)) return;
      const key = `${t.line}:${t.col}`;
      if (!map.has(key)) map.set(key, i);
    });
    return map;
  }

  /**
   * @param {any} node @param {any} parent @param {number} index
   * @param {number|null} badId @param {Map<string, number>} tokenAt @param {boolean} [pending]
   * @returns {HTMLElement}
   */
  function renderNode(node, parent, index, badId, tokenAt, pending = false) {
    const row = el("span", { class: "row", "data-id": node.id });
    if (parent) row.append(el("span", { class: "idx" }, [role(parent, index)]));
    row.append(el("span", { class: `k ${kindClass(node.kind)}` }, [node.kind]));
    if (node.name != null) row.append(el("span", { class: "name" }, [node.name]));
    const v = SimApi.valueLabel(node);
    if (v && node.kind !== "TYPE_ANNOTATION") row.append(el("span", { class: "val" }, [v]));
    if (node.kind === "TYPE_ANNOTATION") row.append(el("span", { class: "type" }, [node.dataType]));
    for (const f of SimApi.flagNames(node)) row.append(el("span", { class: "flag" }, [f]));
    if (node.kind !== "TYPE_ANNOTATION" && node.dataType) row.append(el("span", { class: "type" }, [":" + node.dataType]));
    const sym = SimApi.symbolLabel(node);
    if (sym) row.append(el("span", { class: "sym" }, [sym]));
    if (node.kind === "NONE") row.classList.add("none");
    if (state.known >= 0 && node.id >= state.known) row.classList.add("new");
    if (node.id === badId) row.classList.add("bad");
    if (pending) row.classList.add("pending");
    row.title = `${node.kind} at ${node.line}:${node.col}`;
    const t = tokenAt.get(`${node.line}:${node.col}`);
    if (t !== undefined) {
      row.addEventListener("mouseenter", () => { state.hoverToken = t; hoverSource(); });
      row.addEventListener("mouseleave", () => { state.hoverToken = null; hoverSource(); });
    }

    const li = el("li");
    if (!node.children.length) {
      row.classList.add("leaf");
      li.append(row);
      return li;
    }
    const details = el("details", { open: true });
    details.append(el("summary", {}, [row]));
    const ul = el("ul");
    node.children.forEach((/** @type {any} */ c, /** @type {number} */ i) => ul.append(renderNode(c, node, i, badId, tokenAt, pending)));
    details.append(ul);
    li.append(details);
    return li;
  }

  function hoverSource() {
    if (last) renderSource(last);
  }

  // --- blocks & scopes ---

  /** @param {any} r */
  function renderBlocks(r) {
    const box = $("blocks");
    box.textContent = "";
    const tree = r.semaTree || r.parseTree;
    if (!tree) {
      box.append(el("p", { class: "muted" }, ["Blocks appear as the parser opens them."]));
      return;
    }
    const open = new Set(r.parser.openBlocks || []);
    const global = r.scopes.find((/** @type {any} */ s) => s.kind === "global");
    const root = scopeBox("global scope", "k-global", global ? "functions, built-ins, members" : "filled by semantic analysis");
    if (global) root.append(symbolTable(global, true));
    const kids = el("div", { class: "kids" });
    collectOwners(tree, kids, open);
    root.append(kids);
    box.append(root);
    if (!r.semaTree)
      box.append(el("p", { class: "muted" }, ["Symbols, types and slots are filled in once the program is parsed and semantic analysis runs (send EOF)."]));
  }

  /** @param {string} title @param {string} cls @param {string} sub @param {string} [note] */
  function scopeBox(title, cls, sub, note) {
    const head = el("div", { class: "head" }, [el("b", {}, [title]), el("span", {}, [sub])]);
    if (note) head.append(el("span", {}, [note]));
    return el("div", { class: `scope ${cls}` }, [head]);
  }

  /** @param {any} node @param {HTMLElement} into @param {Set<number>} open */
  function collectOwners(node, into, open) {
    for (const child of node.children) {
      if (child.kind === "DEF" || child.kind === "BLOCK" || child.kind === "FOR") {
        into.append(ownerBox(child, open));
      } else collectOwners(child, into, open);
    }
  }

  /** @param {any} node @param {Set<number>} open */
  function ownerBox(node, open) {
    let title = "";
    let cls = "k-block";
    let sub = `${node.kind} at ${node.line}:${node.col}`;
    if (node.kind === "DEF") {
      const name = node.children[0] ? node.children[0].name : "?";
      title = `def ${name}${node.flags & SimApi.F.MAIN ? " (@main)" : ""}`;
      cls = "k-params";
      sub = "parameter scope";
    } else if (node.kind === "FOR") {
      title = `for ${node.children[0] ? node.children[0].name : ""}`;
      cls = "k-for";
      sub = "loop-variable scope";
    } else {
      const p = node.parent;
      const where = p ? (p.kind === "DEF" ? "function body" : p.kind === "IF" ? (p.children[1] === node ? "then branch" : "else branch") :
        p.kind === "WHILE" ? "while body" : p.kind === "FOR" ? "for body" : "block") : "block";
      title = `BLOCK — ${where}`;
      sub = `${node.children.length} statement${node.children.length === 1 ? "" : "s"}`;
    }
    const isOpen = open.has(node.id);
    const box = scopeBox(title, cls, sub, isOpen ? "open — waiting for its block close" : undefined);
    if (isOpen) box.classList.add("open");
    if (state.known >= 0 && node.id >= state.known) box.classList.add("new-block");
    if (node.scope) box.append(symbolTable(node.scope, false));
    const kids = el("div", { class: "kids" });
    collectOwners(node, kids, open);
    if (kids.childNodes.length) box.append(kids);
    return box;
  }

  /** @param {any} scope @param {boolean} isGlobal */
  function symbolTable(scope, isGlobal) {
    const wrap = el("div");
    const rows = [];
    const builtins = [];
    for (const sym of scope.symbols.values()) {
      if (isGlobal && sym.builtin) builtins.push(sym);
      else rows.push(sym);
    }
    if (rows.length) wrap.append(symRows(rows));
    else if (!isGlobal) wrap.append(el("div", { class: "muted" }, ["no declarations"]));
    if (builtins.length) {
      const d = el("details", {}, [el("summary", {}, [`${builtins.length} built-ins and members`])]);
      d.append(symRows(builtins));
      wrap.append(d);
    }
    return wrap;
  }

  /** @param {any[]} syms */
  function symRows(syms) {
    const table = el("table", { class: "syms" });
    for (const s of syms) {
      let kind;
      let where;
      if (s.kind === "variable") {
        kind = s.declKind || (s.isVal ? "val" : "var");
        where = `@${s.index}`;
      } else if (s.kind === "member") {
        kind = "member";
        where = "";
      } else {
        kind = s.builtin ? "built-in" : `def, ${s.declKind}`;
        where = s.builtin ? "" : `fn${s.index}`;
      }
      const sig = s.kind === "function" ? `(${s.paramTypes.map((/** @type {string} */ p) => p === "Unit" && s.builtin ? "any" : p).join(", ")}) → ${s.type}` : s.kind === "member" ? `→ ${s.type}` : s.type;
      table.append(el("tr", {}, [
        el("td", {}, [s.name]), el("td", { class: "muted" }, [kind]), el("td", {}, [sig]), el("td", { class: "muted" }, [where]),
      ]));
    }
    return table;
  }

  // --- parser state ---

  /** @param {any} r */
  function renderParserState(r) {
    const ind = $("indents");
    ind.textContent = "";
    r.indents.forEach((/** @type {number} */ n, /** @type {number} */ i) =>
      ind.append(el("span", { class: `tok${i === r.indents.length - 1 ? " top" : ""}`, title: i === r.indents.length - 1 ? "current block" : "enclosing block" }, [String(n)])));

    const calls = $("calls");
    calls.textContent = "";
    if (r.status === "waiting" || r.status === "error") {
      for (const c of r.callStack || []) calls.append(el("li", {}, [c]));
    } else if (r.parseTree) calls.append(el("li", { class: "muted" }, ["the parse is finished"]));

    const prec = $("prec");
    prec.textContent = "";
    if (!r.prec.length) prec.append(el("span", { class: "muted" }, [r.status === "waiting" ? "empty, no expression is being parsed" : "empty"]));
    for (const e of r.prec) {
      if (e.kind === "H") prec.append(el("span", { class: "e h", title: "handle start" }, ["<"]));
      else if (e.kind === "E") prec.append(el("span", { class: "e x", title: SimApi.toTestString(e.node) }, ["E " + short(e.node)]));
      else if (e.term === 11) prec.append(el("span", { class: "e end", title: "bottom of a frame" }, ["$"]));
      else if (e.term === 10) prec.append(el("span", { class: "e x", title: e.node ? SimApi.toTestString(e.node) : "" }, ["i " + (e.node ? short(e.node) : "")]));
      else prec.append(el("span", { class: "e" }, [SimApi.PREC_NAMES[e.term] + (e.node && e.node.name ? e.node.name : "")]));
    }

    const seen = $("seen");
    seen.textContent = "";
    const list = r.parser.seen.slice(-60);
    for (const t of list) {
      const cls = t.role === "block open" ? "tok open" : t.role === "block close" ? "tok close" : "tok";
      const label = t.role === "block open" ? `open ${t.value}` : t.role === "block close" ? "close" : tokenLabel(t);
      seen.append(el("span", { class: cls, title: SimApi.describe(t) }, [label]));
    }
    seen.scrollTop = seen.scrollHeight;
  }

  /** @param {any} node */
  function short(node) {
    const s = SimApi.toTestString(node);
    return s.length > 42 ? s.slice(0, 40) + "…" : s;
  }

  // --- trace ---

  /** @param {any} r */
  function renderTrace(r) {
    for (const b of document.querySelectorAll("[data-trace]"))
      b.setAttribute("aria-selected", String(/** @type {HTMLElement} */ (b).dataset.trace === state.trace));
    const box = $("trace");
    box.textContent = "";
    if (state.trace === "parser") {
      const lines = r.parser.trace.slice(-400);
      if (!lines.length) box.append(el("li", { class: "phase" }, ["No tokens consumed yet."]));
      for (const l of lines) box.append(el("li", {}, [l]));
      box.scrollTop = box.scrollHeight;
      return;
    }
    if (!r.semaTrace.length) {
      box.append(el("li", { class: "phase" }, ["Semantic analysis has not run yet: it starts after the parser has read EOF."]));
      return;
    }
    let phase = "";
    const names = { setup: "Setup", "phase 0": "Phase 0 — member entries", "phase 1": "Phase 1 — function collection",
      "phase 2": "Phase 2 — function bodies", "phase 3": "Phase 3 — call cycles" };
    for (const e of r.semaTrace) {
      if (e.phase !== phase) {
        phase = e.phase;
        box.append(el("li", { class: "phase" }, [/** @type {any} */ (names)[phase] || phase]));
      }
      const li = el("li", e.node ? { "data-node": e.node.id, title: "show in the AST" } : {}, [e.text]);
      if (e.node) li.addEventListener("click", () => {
        state.view = "sema";
        state.focusNode = e.node.id;
        render();
      });
      box.append(li);
    }
    if (r.status === "error" && r.error)
      box.append(el("li", { class: "phase" }, [`✗ stopped with exit ${r.exitCode}: ${r.error.message}`]));
  }

  // === COPY ===

  /** @param {string} text @param {HTMLElement} button */
  function copy(text, button) {
    const done = () => {
      const old = button.textContent;
      button.textContent = "Copied";
      setTimeout(() => { button.textContent = old; }, 1200);
    };
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(done, () => fallbackCopy(text, done));
    } else fallbackCopy(text, done);
  }

  /** @param {string} text @param {() => void} done */
  function fallbackCopy(text, done) {
    const ta = el("textarea", {}, [text]);
    document.body.append(ta);
    /** @type {HTMLTextAreaElement} */ (ta).select();
    try { document.execCommand("copy"); done(); } catch (_) { /* nothing to do */ }
    ta.remove();
  }

  // === EVENTS ===

  /** @param {string} id */
  function loadScenario(id) {
    const s = scenarios.find((x) => x.id === id);
    state.scenario = s ? s.id : "";
    state.tokens = s ? SimApi.readScript(s.script) : [];
    state.sent = 0;
    state.known = -1;
    state.view = "parse";
    state.hadSema = false;
    render();
  }

  function bind() {
    $("token-type").addEventListener("change", syncValueField);
    $("send-form").addEventListener("submit", (e) => {
      e.preventDefault();
      const type = /** @type {HTMLSelectElement} */ ($("token-type")).value;
      const input = /** @type {HTMLInputElement} */ ($("token-value"));
      const token = makeToken(type, input.value);
      if (!token) {
        input.setCustomValidity("This value does not fit the token type");
        input.reportValidity();
        return;
      }
      input.setCustomValidity("");
      send(token);
    });
    $("token-value").addEventListener("input", () => /** @type {HTMLInputElement} */ ($("token-value")).setCustomValidity(""));
    $("script-form").addEventListener("submit", (e) => {
      e.preventDefault();
      const input = /** @type {HTMLInputElement} */ ($("script-input"));
      try {
        const toks = SimApi.readScript(input.value);
        if (!toks.length) return;
        input.setCustomValidity("");
        input.value = "";
        send(...toks);
      } catch (err) {
        input.setCustomValidity(/** @type {Error} */ (err).message);
        input.reportValidity();
      }
    });
    $("script-input").addEventListener("input", () => /** @type {HTMLInputElement} */ ($("script-input")).setCustomValidity(""));
    for (const b of document.querySelectorAll("[data-quick]")) {
      b.addEventListener("click", () => {
        const q = /** @type {HTMLElement} */ (b).dataset.quick || "";
        if (q === "EOF") send({ type: "EOF_TOKEN" });
        else send({ type: "EOL_TOKEN" }, { type: "INDENT", value: Number(q.split("+")[1]) });
      });
    }
    $("scenario").addEventListener("change", (e) => loadScenario(/** @type {HTMLSelectElement} */ (e.target).value));
    $("btn-start").addEventListener("click", () => { state.sent = 0; render(); });
    $("btn-back").addEventListener("click", () => { state.sent = Math.max(0, state.sent - 1); render(); });
    $("btn-step").addEventListener("click", () => { state.sent = Math.min(state.tokens.length, state.sent + 1); render(); });
    $("btn-end").addEventListener("click", () => { state.sent = state.tokens.length; render(); });
    $("btn-clear").addEventListener("click", () => {
      /** @type {HTMLSelectElement} */ ($("scenario")).value = "";
      loadScenario("");
    });
    $("btn-copy-c").addEventListener("click", (e) =>
      copy(SimApi.toCTokens(state.tokens.slice(0, state.sent)), /** @type {HTMLElement} */ (e.currentTarget)));
    for (const b of document.querySelectorAll("[data-view]"))
      b.addEventListener("click", () => { state.view = /** @type {HTMLElement} */ (b).dataset.view || "parse"; render(); });
    for (const b of document.querySelectorAll("[data-trace]"))
      b.addEventListener("click", () => { state.trace = /** @type {HTMLElement} */ (b).dataset.trace || "sema"; render(); });
    document.addEventListener("keydown", (e) => {
      if (!e.altKey) return;
      if (e.key === "ArrowRight") { e.preventDefault(); $("btn-step").click(); }
      if (e.key === "ArrowLeft") { e.preventDefault(); $("btn-back").click(); }
    });
  }

  /** `#widening` loads a scenario, `#widening@12` also sends its first 12 tokens */
  function fromHash() {
    const m = /^#([\w-]+)(?:@(\d+|end))?$/.exec(typeof location !== "undefined" ? location.hash : "");
    if (!m || !scenarios.some((x) => x.id === m[1])) return false;
    /** @type {HTMLSelectElement} */ ($("scenario")).value = m[1];
    loadScenario(m[1]);
    if (m[2]) {
      state.sent = m[2] === "end" ? state.tokens.length : Math.min(Number(m[2]), state.tokens.length);
      render();
    }
    return true;
  }

  fillPickers();
  syncValueField();
  bind();
  if (!fromHash()) {
    if (load()) /** @type {HTMLSelectElement} */ ($("scenario")).value = state.scenario;
    render();
  }
})();
